import{z as i,x as s,o as l,c as p,q as t,j as o,D as e,d as B,s as r,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"长上下文的显存账","description":"","frontmatter":{"title":"长上下文的显存账","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lc-memory-account.md","filePath":"llm/lc-memory-account.md","lastUpdated":1791413859000}'),d={name:"llm/lc-memory-account.md"};function m(D,E,C,K,f,c){const A=s("Mermaid");return l(),p("div",null,[E[2]||(E[2]=t('<h1 id="长上下文的显存账" tabindex="-1">长上下文的显存账 <a class="header-anchor" href="#长上下文的显存账" aria-label="Permalink to &quot;长上下文的显存账&quot;">​</a></h1><div class="epigraph"><p>「支持 128K」是模型的窗口声明；能不能在一张 80 GiB 的卡上同时接住三条这样的请求，是显存账本上的算术。</p><footer>—— 据 Pope et al., 2022 的推理容量会计与 Kwon et al., vLLM, SOSP 2023 的页池水位口径整理</footer></div><p><a href="/llm/dec-map">上一课</a>把解码控制与服务化收进一条交付线：受控生成怎么进核，停止、流式与后处理怎么接，质量与成本怎么定价。解码的合同立完，本课程转入窗口本身：上下文从 4K 走到 128K，服务端多出来的字节、拍数与失败模式，都得先有账本再谈优化。主干已把<a href="/llm/long-context-memory-curve">三条显存曲线</a>画全，<a href="/llm/kv-longcontext-budget">长上下文的 KV 预算</a>把 KV 一项编成了预算表。本课作为「显存与调度」单元的第一课，把一条长请求的<strong>完整</strong>账单立起来——账不止 KV 一项，而且账随时间变。后课的切块、分层与调度，默认这套会计已经成立。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把显存想成「权重加 KV」两项，会在两头错。准入时乐观：prefill 要为整段提示付激活峰值，长提示这一拍的临时占用可能比稳态解码多出数 GiB——装得下 KV 不等于跑得完 prefill。运行时悲观：只按峰值记账，忽略分页与共享的弹性，把本可接下的请求拒在门外。更隐蔽的是按「条数」调度：一条 128K 请求占的页数是一条 2K 请求的 64 倍，调度器若把两者当成等价的「一个请求」，池子会在第六十条请求附近替你做决定——这正是<a href="/llm/kv-longcontext-budget">预算课</a>的容量警告在调度侧的复现。缺口于是有二：账单的<strong>栏目</strong>要全，账单的<strong>时间维</strong>要立。</p><p><span class="marginnote">数字实例：8B 模型 FP16 下每 token 的 KV 是 128 KiB，一条 128K 请求光 KV 就要 128K × 128 KiB = 16 GiB——一张 80 GiB 的卡扣掉权重与常数后，同时只接得住两三条这样的请求。「支持 128K」和「同时服务几条 128K」是两个完全不同的问题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一条长请求的账记四栏。常数栏：权重（量化后）、CUDA 上下文、通信缓冲，与 \\(n\\) 无关，扣掉即得可用池。KV 栏：代入<a href="/llm/kv-cache-size-math">容量公式</a>，再乘量化与压缩因子，口径照抄预算课，不重推。峰值栏：prefill 激活随块内 token 数线性涨（见<a href="/llm/prefill-compute">前填计算特征</a>，切块后由块长决定），FlashAttention 使注意力统计不物化 \\(n\\times n\\)，但激活与 logits 缓冲仍在满池水位上是压垮准入的最后一格。结构栏：<a href="/llm/kv-paging-fragmentation">页内与池间碎片</a>，以及为抢占与增长预留的水位。</p><p>再把账放上时间轴。占用是分段函数：准入时按页预算占位；prefill 各拍把激活峰叠加在已写入的 KV 之上；解码段 KV 常驻并缓涨，直到释放。占用乘以驻留时长，得<strong>显存·时间积</strong>——它是这条请求的真实资源价。准入与排队应按积定价，而不是按条数。</p>',9)),(l(),o(n,null,{default:e(()=>[r(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADM%5B%22%E5%87%86%E5%85%A5%EF%BC%9A%E6%8C%89%E9%A1%B5%E9%A2%84%E7%AE%97%E5%8D%A0%E4%BD%8D%22%5D%20--%3E%20PRE%5B%22prefill%20%E5%90%84%E6%8B%8D%EF%BC%9A%E6%BF%80%E6%B4%BB%E5%B3%B0%E5%8F%A0%E5%8A%A0%E5%9C%A8%20KV%20%E4%B8%8A%22%5D%0A%20%20PRE%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E6%AE%B5%EF%BC%9AKV%20%E5%B8%B8%E9%A9%BB%E7%BC%93%E6%B6%A8%22%5D%0A%20%20DEC%20--%3E%20REL%5B%22%E9%87%8A%E6%94%BE%EF%BC%9A%E9%A1%B5%E5%BD%92%E8%BF%98%E6%B1%A0%22%5D%0A%20%20PRE%20-.-%3E%7C%22%E5%B3%B0%E5%80%BC%E6%A0%8F%E7%94%B1%E5%9D%97%E9%95%BF%E5%86%B3%E5%AE%9A%22%7C%20PEAK%5B%22%E4%B8%B4%E6%97%B6%E5%8D%A0%E7%94%A8%E5%B3%B0%E5%80%BC%22%5D%0A%20%20DEC%20-.-%3E%7C%22KV%20%E6%A0%8F%EF%BC%9A%E5%85%AC%E5%BC%8F%20%C3%97%20%E5%8E%8B%E7%BC%A9%E5%9B%A0%E5%AD%90%22%7C%20OCC%5B%22%E5%B8%B8%E9%A9%BB%E5%8D%A0%E7%94%A8%22%5D%0A%20%20PEAK%20--%3E%20PRICE%5B%22%E6%98%BE%E5%AD%98%C2%B7%E6%97%B6%E9%97%B4%E7%A7%AF%20%3D%20%E5%8D%A0%E7%94%A8%20%C3%97%20%E9%A9%BB%E7%95%99%E6%97%B6%E9%95%BF%22%5D%0A%20%20OCC%20--%3E%20PRICE%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"调度器的硬约束是块池水位，不是请求个数，这决定了记账单位是页而非条。混合负载里，一条满长请求能把可用并发从几十压到个位，队列里每个短请求都在替它付排队成本——按条数准入等于让 2K 请求补贴 128K 请求。显存·时间积同时是定价语义：API 按 token 计费看不见排队外部性，内部容量规划必须用积，否则扩容决策会系统性低估长请求的份额。峰值栏与 KV 栏可以互相兑换：把前填切小，峰值换下来，代价是反复读 KV 的带宽税——兑换率由块长决定，下一课细算。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"算一笔积：2K 请求占 256 MiB、驻留一分钟，积约 15 GiB·s；128K 请求占 16 GiB（FP16，8B 模型每 token 128 KiB）、驻留十分钟，积 9600 GiB·s——640 倍。按条数它们等价，按积它们差出三个数量级的一半以上。")],-1)),E[6]||(E[6]=a("p",null,"「记账单位是页而非条」值得单独画出来：同一个池子，两种记账，结局完全不同。",-1)),(l(),o(n,null,{default:e(()=>[r(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20POOL%5B%22%E9%A1%B5%E6%B1%A0%EF%BC%9A%E5%8F%AF%E7%94%A8%E6%98%BE%E5%AD%98%E6%8C%89%E9%A1%B5%E8%AE%A1%22%5D%20--%3E%20Q%7B%22%E5%87%86%E5%85%A5%E6%8C%89%E4%BB%80%E4%B9%88%E8%AE%B0%E8%B4%A6%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%8C%89%E6%9D%A1%E6%95%B0%22%7C%20C1%5B%22128K%20%E4%B8%8E%202K%20%E9%83%BD%E7%AE%97%201%20%E6%9D%A1%22%5D%0A%20%20C1%20--%3E%20BAD%5B%22%E7%BA%A6%E7%AC%AC%E5%85%AD%E5%8D%81%E6%9D%A1%E6%97%B6%E6%B1%A0%E5%AD%90%E7%AA%81%E7%84%B6%E8%A7%81%E5%BA%95%22%5D%0A%20%20BAD%20--%3E%20OOM%5B%22OOM%20%2F%20%E6%8A%A2%E5%8D%A0%E9%A3%8E%E6%9A%B4%22%5D%0A%20%20Q%20--%3E%7C%22%E6%8C%89%E9%A1%B5%E6%95%B0%22%7C%20C2%5B%22128K%20%E5%8D%A0%2064%20%E5%80%8D%E9%A1%B5%E6%95%B0%22%5D%0A%20%20C2%20--%3E%20OK%5B%22%E6%B0%B4%E4%BD%8D%E9%9A%8F%E7%A7%AF%E7%B2%BE%E7%A1%AE%E4%B8%8B%E9%99%8D%22%5D%0A%20%20OK%20--%3E%20FAIR%5B%22%E7%9F%AD%E8%AF%B7%E6%B1%82%E4%B8%8D%E5%86%8D%E8%A1%A5%E8%B4%B4%E9%95%BF%E8%AF%B7%E6%B1%82%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p><span class="marginnote">术语翻译：KV 缓存是模型在生成时为每个已处理 token 留下的「中间计算结果备忘录」——没有它，每生成一个字都要把前面所有内容重算一遍。它随 token 数线性变长，所以长上下文的第一笔账永远是 KV 的账。</span></p><p><span class="marginnote">常见误区：容易以为「KV 装得下就跑得动」。实际上 prefill 一拍要为整块 token 付激活峰值，长提示在准入那一刻的临时占用可能比稳态解码高数 GiB——这正是「装得下 KV 不等于跑得完 prefill」的出处，也是准入要按峰值栏复核的原因。</span></p><p>本课只进容量侧：decode 每步扫 KV 的带宽账是<a href="/llm/kv-longcontext-budget">预算课</a>的第二张表，这里不重复。峰值栏依赖实现——注意力统计是否物化、激活是否重算——给区间不给常数，换核要重测。启用 offload 后账记两处，HBM 与主机的口径由「上下文缓存的分层」一课展开。最后，账随模型、精度与压缩策略版本化：升级模型重记账，旧账不能沿用——这条纪律从主干一路贯到这里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长请求的显存账四栏：常数、KV、峰值、结构损耗；只记「权重加 KV」会在准入与运行两头错。</li><li>账随生命周期分段：prefill 付激活峰，解码段 KV 常驻，占用乘驻留时长才是资源价。</li><li>准入与定价的记账单位是页与显存·时间积，不是请求条数。</li><li>峰值与常驻可以互相兑换，兑换率由块长决定，是下一课的主题。</li><li>账本版本化：模型、精度、压缩策略一变，账重记。</li><li>出处：据 Pope et al., 2022；Kwon et al., SOSP 2023 的容量会计口径，与本仓库 KV 容量、预算、分页诸课整理。</li></ul>',6))])}const V=i(d,[["render",m]]);export{u as __pageData,V as default};
